import 'dart:convert';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
void main() => runApp(const ChayanApp());
const categories = ['Bengali Movie', 'Hindi Movie', 'English Movie'];
const sheetUrl = 'https://docs.google.com/spreadsheets/d/11_YGayUIDDDTUGMravPYCOHdZSzJWn7l1RoI4h8XESM/edit';
class ChayanApp extends StatelessWidget {
 const ChayanApp({super.key});
 @override Widget build(BuildContext context) => MaterialApp(title:'Chayan Entertainment',debugShowCheckedModeBanner:false,
 theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFF6254D9),brightness:Brightness.dark),scaffoldBackgroundColor:const Color(0xFF10111A)),home:const MovieManager());
}
class MovieRow {
 const MovieRow(this.id,this.name,this.year,this.category,this.posterUrl);
 final String id,name,category,posterUrl; final int year;
 factory MovieRow.fromJson(Map<String,dynamic> j)=>MovieRow('${j['id']??''}','${j['name']??''}',int.tryParse('${j['year']??0}')??0,categories.contains(j['category'])?'${j['category']}':'English Movie','${j['posterUrl']??j['poster']??''}');
 Map<String,dynamic> toJson()=>{'id':id,'name':name,'year':year,'category':category,'posterUrl':posterUrl};
}
class MovieManager extends StatefulWidget { const MovieManager({super.key}); @override State<MovieManager> createState()=>_MovieManagerState(); }
class _MovieManagerState extends State<MovieManager> {
 final name=TextEditingController(),year=TextEditingController(text:DateTime.now().year.toString()),poster=TextEditingController(),search=TextEditingController(),endpoint=TextEditingController();
 List<MovieRow> movies=[]; String category=categories.first,status='Connect Google Sheets to manage your movie library.',editingId=''; bool busy=false;
 @override void initState(){super.initState();init();}
 @override void dispose(){name.dispose();year.dispose();poster.dispose();search.dispose();endpoint.dispose();super.dispose();}
 Future<void> init() async {final p=await SharedPreferences.getInstance();endpoint.text=p.getString('sheets_endpoint')??'';if(endpoint.text.isNotEmpty)await loadMovies();}
 Future<Map<String,dynamic>> request(Map<String,dynamic> body) async {
  final uri=Uri.tryParse(endpoint.text.trim());if(uri==null||uri.scheme!='https'||!uri.path.endsWith('/exec'))throw Exception('Enter the deployed Apps Script URL ending in /exec.');
  final client=HttpClient()..connectionTimeout=const Duration(seconds:25);
  try {final req=await client.postUrl(uri);req.headers.contentType=ContentType('application','json',charset:'utf-8');req.write(jsonEncode(body));final response=await req.close().timeout(const Duration(seconds:35));final decoded=jsonDecode(await response.transform(utf8.decoder).join());
   if(decoded is! Map<String,dynamic>)throw Exception('Unexpected response from Google Sheets.');if(decoded['ok']!=true)throw Exception('${decoded['error']??'Google Sheets request failed.'}');return decoded;
  } finally {client.close(force:true);}
 }
 Future<void> loadMovies() async {setState(() { busy=true; status='Loading from Google Sheets…'; });try{final p=await SharedPreferences.getInstance();await p.setString('sheets_endpoint',endpoint.text.trim());final r=await request({'action':'list'});movies=(r['movies'] as List? ?? []).map((e)=>MovieRow.fromJson(Map<String,dynamic>.from(e as Map))).toList()..sort((a,b)=>a.name.toLowerCase().compareTo(b.name.toLowerCase()));setState(()=>status='Connected. '+movies.length.toString()+' movies loaded.');}catch(e){setState(()=>status='Connection failed: '+e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> saveMovie() async {final y=int.tryParse(year.text.trim());if(name.text.trim().isEmpty||y==null||y<1888||y>DateTime.now().year+10){setState(()=>status='Enter a movie title and valid release year.');return;}setState(() { busy=true; status='Saving to Google Sheets…'; });final m=MovieRow(editingId.isEmpty?DateTime.now().microsecondsSinceEpoch.toString():editingId,name.text.trim(),y,category,poster.text.trim());try{await request({'action':'upsert','movie':m.toJson()});clearForm();await loadMovies();setState(()=>status='Movie saved to Google Sheets.');}catch(e){setState(()=>status='Save failed: '+e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>busy=false);}}
 void clearForm(){name.clear();year.text=DateTime.now().year.toString();poster.clear();setState(() { editingId=''; category=categories.first; });}
 void edit(MovieRow m){setState(() { editingId=m.id; category=m.category; });name.text=m.name;year.text=m.year.toString();poster.text=m.posterUrl;}
 Future<void> deleteMovie(MovieRow m) async {final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Delete movie?'),content:Text('Remove "'+m.name+'" from the sheet?'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Delete'))]));if(ok!=true)return;setState(() { busy=true; status='Deleting…'; });try{await request({'action':'delete','id':m.id});await loadMovies();setState(()=>status='Movie deleted.');}catch(e){setState(()=>status='Delete failed: '+e.toString());}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> connect() async {final c=TextEditingController(text:endpoint.text);final value=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Connect Google Sheets'),content:SizedBox(width:520,child:Column(mainAxisSize:MainAxisSize.min,children:[const Text('Paste the deployed Google Apps Script web app URL ending in /exec.'),const SizedBox(height:12),TextField(controller:c,decoration:const InputDecoration(labelText:'Apps Script URL'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,c.text.trim()),child:const Text('Save'))]));if(value!=null){endpoint.text=value;await loadMovies();}}
 @override Widget build(BuildContext context){final q=search.text.trim().toLowerCase();final shown=movies.where((m)=>m.name.toLowerCase().contains(q)&&(q.isNotEmpty||m.category==category)).toList();return Scaffold(
 appBar:AppBar(title:const Text('CHAYAN ENTERTAINMENT',style:TextStyle(fontWeight:FontWeight.w900,letterSpacing:1)),actions:[TextButton.icon(onPressed:busy?null:connect,icon:const Icon(Icons.link),label:const Text('Sheets connection')),TextButton.icon(onPressed:()=>Process.run('cmd',['/c','start','',sheetUrl]),icon:const Icon(Icons.open_in_new),label:const Text('Open Google Sheet')),const SizedBox(width:12)]),
 body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:1180),child:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[
 Text('MOVIE MANAGER',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:5),const Text('Add and manage records here. Your Google Sheet is the library and dashboard.'),const SizedBox(height:18),
 Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(editingId.isEmpty?'ADD A MOVIE':'EDIT MOVIE',style:const TextStyle(fontWeight:FontWeight.w900,letterSpacing:1.2)),const SizedBox(height:14),
 Wrap(spacing:12,runSpacing:12,children:[SizedBox(width:290,child:TextField(controller:name,decoration:const InputDecoration(labelText:'Movie title',border:OutlineInputBorder(),prefixIcon:Icon(Icons.movie_outlined)))),SizedBox(width:140,child:TextField(controller:year,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Release year',border:OutlineInputBorder()))),SizedBox(width:210,child:DropdownButtonFormField<String>(value:category,decoration:const InputDecoration(labelText:'Category',border:OutlineInputBorder()),items:categories.map((c)=>DropdownMenuItem(value:c,child:Text(c))).toList(),onChanged:busy?null:(v){if(v!=null)setState(()=>category=v);})),SizedBox(width:360,child:TextField(controller:poster,decoration:const InputDecoration(labelText:'Poster image URL (optional)',border:OutlineInputBorder(),prefixIcon:Icon(Icons.image_outlined))))]),
 const SizedBox(height:14),Wrap(spacing:10,children:[FilledButton.icon(onPressed:busy?null:saveMovie,icon:Icon(editingId.isEmpty?Icons.add:Icons.save),label:Text(editingId.isEmpty?'Save movie to sheet':'Update movie')),OutlinedButton.icon(onPressed:busy?null:clearForm,icon:const Icon(Icons.clear),label:const Text('Clear form')),OutlinedButton.icon(onPressed:busy?null:loadMovies,icon:const Icon(Icons.sync),label:const Text('Refresh from sheet'))])]))),
 const SizedBox(height:8),Row(children:[Expanded(child:Text(status,maxLines:2,overflow:TextOverflow.ellipsis)),if(busy)const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2))]),const SizedBox(height:12),
 Row(children:[Text('SHEET RECORDS',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(width:12),Chip(label:Text(movies.length.toString()+' total')),const Spacer(),SizedBox(width:280,child:TextField(controller:search,onChanged:(_)=>setState((){}),decoration:const InputDecoration(isDense:true,prefixIcon:Icon(Icons.search),hintText:'Search titles',border:OutlineInputBorder())))]),const SizedBox(height:8),
 Expanded(child:movies.isEmpty?Center(child:Text(endpoint.text.isEmpty?'Connect your Google Apps Script deployment to begin.':'No movies loaded yet.')):ListView.separated(itemCount:shown.length,separatorBuilder:(_,__)=>const SizedBox(height:4),itemBuilder:(ctx,i){final m=shown[i];return Card(child:ListTile(leading:CircleAvatar(child:Text(m.name.isEmpty?'?':m.name[0].toUpperCase())),title:Text(m.name),subtitle:Text(m.year.toString()+' • '+m.category+(m.posterUrl.isEmpty?'':' • Poster URL available')),trailing:Wrap(spacing:2,children:[IconButton(tooltip:'Edit',onPressed:busy?null:()=>edit(m),icon:const Icon(Icons.edit_outlined)),IconButton(tooltip:'Delete',onPressed:busy?null:()=>deleteMovie(m),icon:const Icon(Icons.delete_outline))])));})),
 ])))));}
}
